<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Database;
use DomainException;
final class CredentialService{
public function __construct(private readonly Database$db){}
public function create(string$type,int$recordId,int$instituteId,string$email,int$creator,?string$password=null):array{if(!in_array($type,['student','employee'],true)||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Enter a valid login email.');$plain=$this->password($password);$table=$type==='student'?'students':'employees';$link=$type.'_accounts';$column=$type.'_id';if(!$this->db->query("SELECT 1 FROM {$table} WHERE id=:id AND institute_id=:i",['id'=>$recordId,'i'=>$instituteId])->fetchColumn())throw new DomainException('Record not found.');$existing=$this->db->query("SELECT a.user_id FROM {$link} a JOIN {$table} d ON d.id=a.{$column} WHERE a.{$column}=:id AND d.institute_id=:i",['id'=>$recordId,'i'=>$instituteId])->fetchColumn();$now=date('Y-m-d H:i:s');$cipher=$this->encrypt($plain);if($existing){$this->db->query('UPDATE users SET email=:e,password_hash=:p,status="active",updated_at=:u WHERE id=:id',['e'=>strtolower($email),'p'=>password_hash($plain,PASSWORD_DEFAULT),'u'=>$now,'id'=>$existing]);$this->db->query("UPDATE {$link} SET password_cipher=:secret,updated_at=:u WHERE {$column}=:id",['secret'=>$cipher,'u'=>$now,'id'=>$recordId]);$this->grant((int)$existing,$type,$instituteId);return['user_id'=>(int)$existing,'temporary_password'=>$plain];}$pdo=$this->db->connection();$pdo->beginTransaction();try{$this->db->query('INSERT INTO users(name,email,password_hash,status,created_at,updated_at) SELECT '.($type==='student'?'student_name':'name').',:e,:p,"active",:n,:n2 FROM '.$table.' WHERE id=:id',['e'=>strtolower($email),'p'=>password_hash($plain,PASSWORD_DEFAULT),'n'=>$now,'n2'=>$now,'id'=>$recordId]);$user=(int)$pdo->lastInsertId();$this->db->query("INSERT INTO {$link}({$column},user_id,password_cipher,created_by,created_at,updated_at) VALUES(:r,:u,:secret,:c,:n,:n2)",['r'=>$recordId,'u'=>$user,'secret'=>$cipher,'c'=>$creator,'n'=>$now,'n2'=>$now]);$this->grant($user,$type,$instituteId);$pdo->commit();return['user_id'=>$user,'temporary_password'=>$plain];}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
/** Gives a managed login its portal role and institute membership. Idempotent. */
private function grant(int$userId,string$type,int$instituteId):void{$this->db->query('INSERT IGNORE INTO user_roles(user_id,role_id) SELECT :u,id FROM roles WHERE slug=:slug',['u'=>$userId,'slug'=>$type]);$this->db->query('INSERT IGNORE INTO institute_users(user_id,institute_id,created_at) VALUES(:u,:i,:c)',['u'=>$userId,'i'=>$instituteId,'c'=>date('Y-m-d H:i:s')]);}
public function reveal(?string$cipher):?string{if(!$cipher)return null;$raw=base64_decode($cipher,true);if($raw===false||strlen($raw)<29)return null;$iv=substr($raw,0,12);$tag=substr($raw,12,16);$data=substr($raw,28);$plain=openssl_decrypt($data,'aes-256-gcm',$this->key(),OPENSSL_RAW_DATA,$iv,$tag);return$plain===false?null:$plain;}
private function encrypt(string$plain):string{$iv=random_bytes(12);$tag='';$data=openssl_encrypt($plain,'aes-256-gcm',$this->key(),OPENSSL_RAW_DATA,$iv,$tag);if($data===false)throw new \RuntimeException('Could not protect credential.');return base64_encode($iv.$tag.$data);}
private function key():string{return hash('sha256',(string)(getenv('APP_KEY')?:'arete-managed-credentials'),true);}
private function password(?string$password):string{if($password!==null&&$password!==''){if(strlen($password)<8)throw new DomainException('Password must contain at least 8 characters.');return$password;}return rtrim(strtr(base64_encode(random_bytes(15)),'+/','-_'),'=');}
}
